def check_moore_bound():
    # Just to be absolutely sure, let's run a quick SAT check for 17 edges
    from pysat.solvers import Glucose3
    from pysat.card import CardEnc
    from itertools import combinations, permutations

    n = 13
    target = 17
    solver = Glucose3()
    edges = {}
    var_idx = 1
    for i in range(n):
        for j in range(i+1, n):
            edges[(i, j)] = var_idx
            var_idx += 1

    def get_edge(u, v):
        return edges[tuple(sorted((u, v)))]

    # Length 3
    for c in combinations(range(n), 3):
        solver.add_clause([-get_edge(c[0], c[1]), -get_edge(c[0], c[2]), -get_edge(c[1], c[2])])

    # Length 4
    for c in combinations(range(n), 4):
        solver.add_clause([-get_edge(c[0], c[1]), -get_edge(c[1], c[2]), -get_edge(c[2], c[3]), -get_edge(c[0], c[3])])
        solver.add_clause([-get_edge(c[0], c[2]), -get_edge(c[2], c[1]), -get_edge(c[1], c[3]), -get_edge(c[0], c[3])])
        solver.add_clause([-get_edge(c[0], c[1]), -get_edge(c[1], c[3]), -get_edge(c[3], c[2]), -get_edge(c[0], c[2])])

    cnf = CardEnc.atleast(lits=list(edges.values()), bound=target, encoding=1)
    for clause in cnf.clauses:
        solver.add_clause(clause)

    print(f"Checking {target} edges for girth >= 5...")
    if solver.solve():
        print("SAT")
    else:
        print("UNSAT")

check_moore_bound()
